-- Thêm parent_code + seed 3321 phường/xã từ DIA_CHI.csv

alter table public.reference_options
  add column if not exists parent_code text;

alter table public.reference_options
  drop constraint if exists reference_options_category_check;

alter table public.reference_options
  add constraint reference_options_category_check check (category = any (array[
    'education_level','specialization','political_theory','it_level','foreign_language','occupation',
    'ethnicity','religion','province','ward'
  ]));

